# Generate environment backgrounds
import cv2, numpy as np
w, h = 640, 480

store = np.zeros((h, w, 3), dtype=np.uint8)
for y in range(h): store[y, :] = [int(35 + (y/h)*25), int(20 + (y/h)*15), int(25 + (y/h)*20)]
cv2.circle(store, (160, 80), 120, (50, 140, 200), -1); cv2.circle(store, (480, 80), 120, (50, 140, 200), -1)
store = cv2.GaussianBlur(store, (65, 65), 0)
cv2.putText(store, 'KHAADI FLAGSHIP BOUTIQUE', (120, 50), cv2.FONT_HERSHEY_SIMPLEX, 0.7, (150, 200, 240), 2)
cv2.imwrite('static/environments/khaadi_store.jpg', store)

runway = np.zeros((h, w, 3), dtype=np.uint8)
for y in range(h): runway[y, :] = [int(15 + y*0.05), int(10 + y*0.03), int(25 + y*0.08)]
pts = np.array([[w//2, 0], [w*0.8, h], [w*0.2, h]], np.int32)
cv2.fillPoly(runway, [pts], (80, 70, 50)); runway = cv2.GaussianBlur(runway, (51, 51), 0)
cv2.putText(runway, 'FASHION WEEK RUNWAY', (160, 50), cv2.FONT_HERSHEY_SIMPLEX, 0.7, (200, 220, 255), 2)
cv2.imwrite('static/environments/fashion_runway.jpg', runway)

palace = np.zeros((h, w, 3), dtype=np.uint8)
for y in range(h): palace[y, :] = [int(10 + y*0.08), int(20 + y*0.1), int(40 + y*0.12)]
cv2.ellipse(palace, (w//2, h//2), (240, 180), 0, 180, 360, (40, 80, 140), 12); palace = cv2.GaussianBlur(palace, (45, 45), 0)
cv2.putText(palace, 'ROYAL PALACE COURTYARD', (140, 50), cv2.FONT_HERSHEY_SIMPLEX, 0.7, (180, 210, 255), 2)
cv2.imwrite('static/environments/royal_palace.jpg', palace)

studio = np.zeros((h, w, 3), dtype=np.uint8)
for y in range(h): val = int(30 + (y/h)*40); studio[y, :] = [val, val, val + 15]
cv2.imwrite('static/environments/studio.jpg', studio)

from pyngrok import ngrok
ngrok.set_auth_token(NGROK_TOKEN)

try:
    ngrok.kill()
    tunnel = ngrok.connect(8000)
    public_url = tunnel.public_url
    print("\n" + "★" * 65)
    print(f"✨ PUBLIC APP URL: {public_url}")
    print(f"✨ WEBSOCKET URL:  {public_url.replace('http://', 'ws://').replace('https://', 'wss://')}/ws/tryon")
    print("★" * 65 + "\n")
except Exception as e:
    print(f"Ngrok notice: {e}")
    public_url = "http://localhost:8000"

print("🔥 Launching AI Server...")
subprocess.run([sys.executable, "server.py", "--port", "8000", "--no-tunnel"])
